;; curriculum: Calc-2 (undergrad) — Taylor polynomials; prerequisites: series, sine
;; math target: polynomials hug sin(x): more terms fit the wave over a wider interval.

app riya-level-taylor "1.1.0"
"riya level 22 · Taylor — polynomials chase the sine: the line clings near 0, the cubic clings farther. Collect term pads to widen the road, but watch the edges diverge. Skate the wave — catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism (menu + all eighteen worlds)."

;; @exposure internal

orbital RiyaTaylorOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaTaylorBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaTaylorPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaTaylorFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaTaylorPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaTaylorCurveSample = {
    x : number!
    y : number!
  }
  type RiyaTaylorCurve = {
    label : string
    color : string
    samples : [RiyaTaylorCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaTaylorCurveMod = {
    id : string!
    x0 : number!
    x1 : number!
    a : number!
    h : number!
    k : number!
  }
  type RiyaTaylorFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaTaylorState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaTaylorBody = { x: -9, y: 5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaTaylorPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaTaylorFx] = []
    celebrated : boolean = false
    zoneId : string = "taylor"
    platforms : [RiyaTaylorPlatform] = []
    curves : [RiyaTaylorCurve] = []
    warnSamples : [RiyaTaylorCurveSample] = []
  }

  entity TaylorTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait TaylorBody = Body.traits.PlatformerBody -> RiyaTaylorState {
    events {
      STEER: TAYLOR_STEER
      JUMP: TAYLOR_LEAP
      PLACE: TAYLOR_PLACE
      RESTART: TAYLOR_RESTART
      BODY_MOVED: TAYLOR_MOVED
      BODY_JUMPED: TAYLOR_JUMPED
      BODY_LANDED: TAYLOR_LANDED
      BODY_HAZARD: TAYLOR_HAZARD
      BODY_GOAL: TAYLOR_GOAL
      BODY_FELL: TAYLOR_FELL
      BODY_SKATE_START: TAYLOR_SKATE_ON
      BODY_SKATE_END: TAYLOR_SKATE_OFF
      SET_PLATFORMS: TAYLOR_SET_PLATFORMS
      SET_SKATE_CURVE: TAYLOR_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -9, y: 5, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait TaylorGate = Gate.traits.ObjectiveFlow -> RiyaTaylorState {
    events {
      PROGRESS: TAYLOR_PROGRESS
      GAME_END: TAYLOR_GAME_END
      RESTART: TAYLOR_RESTART
    }
    config { running: true }
  }

  trait TaylorFx = Particles.traits.FxParticles -> RiyaTaylorState {
    events {
      BURST: TAYLOR_BURST
    }
    config { running: true }
  }

  trait TaylorTutorialPreview -> TaylorTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait TaylorTutorial = Tutorial.traits.TutorialOverlay -> TaylorTutorialData {
    events {
      SHOW: TAYLOR_TUTORIAL_SHOW
      TUTORIAL_DONE: TAYLOR_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.TaylorTutorialPreview
      steps: [
        { id: "intro", title: "Taylor", body: "The solid wave is y = 3 + 2·sin(x/2). The dashed line and cubic are Taylor polynomials that hug it near x = 0. Grab T1 and T3 pads to widen the fit, but beware the red divergence zones at the edges." }
      ]
    }
  }

  trait TaylorPickup = Pickup.traits.Pickup -> RiyaTaylorState {
    events {
      PICKED: TAYLOR_PICKED
      COLLECT: TAYLOR_COLLECT
      PICKUP_SET_COMPLETED: TAYLOR_PICKUP_SET_COMPLETED
      SET_FEATURES: TAYLOR_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait TaylorLevelData -> @rebindable RiyaTaylorState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "taylor"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          warnSamples: (array/map @config.warnSamples (fn s @s))
          curveMods: (array/map @config.curveMods (fn m @m))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaTaylorPlatform]!
        stars : [RiyaTaylorPickup]!
        skateCurve : [RiyaTaylorCurveSample]
        curveOverlay : [RiyaTaylorCurve]
        warnSamples : [RiyaTaylorCurveSample]
        curveMods : [RiyaTaylorCurveMod]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Taylor"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 3 + 2·sin(x/2)"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "polynomials hug the wave: the line clings near 0, the cubic clings farther — adding terms widens the accurate region"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 4.9
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge (top of tile b0: −2 + 6.9); the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.1
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge (top of tile b11: −2 + 3.1); the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaTaylorPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 6.9, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 5.9, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 4.3, type: "ground" }
        { id: "b3", x: -4.8, y: -2, width: 1.6, height: 3.2, type: "ground" }
        { id: "b4", x: -3.2, y: -2, width: 1.6, height: 3.1, type: "ground" }
        { id: "b5", x: -1.6, y: -2, width: 1.6, height: 4.2, type: "ground" }
        { id: "b6", x: 0, y: -2, width: 1.6, height: 5.8, type: "ground" }
        { id: "b7", x: 1.6, y: -2, width: 1.6, height: 6.9, type: "ground" }
        { id: "b8", x: 3.2, y: -2, width: 1.6, height: 6.8, type: "ground" }
        { id: "b9", x: 4.8, y: -2, width: 1.6, height: 5.7, type: "ground" }
