  trait RiyaTaylorGenre = Genre.traits.PlatformerPuzzle -> RiyaTaylorState {
    config {
      agencyTrait: @trait.TaylorBody
      challengeTrait: @trait.TaylorBody
      goalTrait: @trait.TaylorGate
      rewardTrait: @trait.TaylorPickup
      feedbackTrait: @trait.TaylorFx
    }
  }

  trait RiyaTaylorPlay -> @rebindable RiyaTaylorState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit TAYLOR_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "TAYLOR_LEFT", KeyA: "TAYLOR_LEFT", ArrowRight: "TAYLOR_RIGHT", KeyD: "TAYLOR_RIGHT", ArrowUp: "TAYLOR_JUMP", KeyW: "TAYLOR_JUMP", Space: "TAYLOR_JUMP" }
            keyUpMap: { ArrowLeft: "TAYLOR_STOP", KeyA: "TAYLOR_STOP", ArrowRight: "TAYLOR_STOP", KeyD: "TAYLOR_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            regions: (array/concat
              [ { samples: (array/filter @entity.warnSamples (fn smp (<= (object/get @smp x) -5))), baseline: 0, color: "#ef4444", opacity: 0.12, label: "diverges" } ]
              [ { samples: (array/filter @entity.warnSamples (fn smp (>= (object/get @smp x) 5))), baseline: 0, color: "#ef4444", opacity: 0.12, label: "diverges" } ])
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "TAYLOR_LEFT", right: "TAYLOR_RIGHT", up: "TAYLOR_JUMP" }, directionReleaseEvents: { left: "TAYLOR_STOP", right: "TAYLOR_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "taylor")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.warnSamples @payload.warnSamples)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit TAYLOR_SET_PLATFORMS { platforms: @payload.platforms })
        (emit TAYLOR_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit TAYLOR_SET_FEATURES { features: @payload.stars })

      TAYLOR_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit TAYLOR_STEER { dir: -1 })

      TAYLOR_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit TAYLOR_STEER { dir: 1 })

      TAYLOR_STOP -> idle when (== @entity.active true)
        (emit TAYLOR_STEER { dir: 0 })

      TAYLOR_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit TAYLOR_LEAP {})

      TAYLOR_FELL -> idle when (== @entity.active true)
        (emit TAYLOR_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit TAYLOR_BURST { particles: (array/map [ "fx-taylor-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      TAYLOR_SKATE_ON -> idle when (== @entity.active true)
        (emit TAYLOR_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "more terms = wider fit", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-taylor-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      TAYLOR_PICKED -> idle when (== @entity.active true)
        (emit TAYLOR_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (object/get @payload glyph), ttl: 2 })) })
      TAYLOR_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit TAYLOR_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      TAYLOR_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit TAYLOR_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "Taylor polynomials chase sin(x)", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit TAYLOR_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      TAYLOR_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "taylor" })

      TAYLOR_TUTORIAL_DONE -> idle
        (emit TAYLOR_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "polynomials hug the wave near x = 0", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "TAYLOR_LEFT", KeyA: "TAYLOR_LEFT", ArrowRight: "TAYLOR_RIGHT", KeyD: "TAYLOR_RIGHT", ArrowUp: "TAYLOR_JUMP", KeyW: "TAYLOR_JUMP", Space: "TAYLOR_JUMP" }
            keyUpMap: { ArrowLeft: "TAYLOR_STOP", KeyA: "TAYLOR_STOP", ArrowRight: "TAYLOR_STOP", KeyD: "TAYLOR_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            regions: (array/concat
              [ { samples: (array/filter @entity.warnSamples (fn smp (<= (object/get @smp x) -5))), baseline: 0, color: "#ef4444", opacity: 0.12, label: "diverges" } ]
              [ { samples: (array/filter @entity.warnSamples (fn smp (>= (object/get @smp x) 5))), baseline: 0, color: "#ef4444", opacity: 0.12, label: "diverges" } ])
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "star") @config.starColor "#f472b6"), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      TAYLOR_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      TAYLOR_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      TAYLOR_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      TAYLOR_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (TAYLOR_LEAP), which accepts it only while grounded."
        @tier "domain"
      TAYLOR_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      TAYLOR_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      TAYLOR_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      TAYLOR_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      TAYLOR_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the wave — fires the equation fx burst."
        @tier "domain"
      TAYLOR_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the star glyph, the challenge trait applies the term-pad curve mods and boost narrative."
        @tier "domain"
      TAYLOR_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      TAYLOR_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      TAYLOR_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow/pickup authorities (renamed RESTART)."
        @tier "domain"
      TAYLOR_BURST -> external {
        particles : [RiyaTaylorFx]
      }
        @description "Particle batch spawned on star pickup, skate engage or pit respawn; fx-particles fades it."
        @tier "domain"
      TAYLOR_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the Play trait; the objective-flow gate resolves won from it."
        @tier "domain"
      TAYLOR_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      TAYLOR_SET_PLATFORMS -> external {
        platforms : [RiyaTaylorPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      TAYLOR_SET_SKATE_CURVE -> external {
        curve : [RiyaTaylorCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate rails."
        @tier "domain"
      TAYLOR_SET_FEATURES -> external {
        features : [RiyaTaylorPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars and term pads."
        @tier "domain"
    }

    listens {
      TAYLOR_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaTaylorPlatform]!
