  trait TaylorChallenge -> @rebindable RiyaTaylorState [game-core, instance] {
    initial: idle

    state idle {
      TAYLOR_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "t1-l")
          (emit TAYLOR_CURVE_MOD_ADD { x0: -5, x1: -2, a: 1, h: 0, k: 0.5 })
          (if (str/endsWith @payload.id "t1-r")
            (emit TAYLOR_CURVE_MOD_ADD { x0: 2, x1: 5, a: 1, h: 0, k: 0.5 })
            (if (str/endsWith @payload.id "t3-l")
              (emit TAYLOR_CURVE_MOD_ADD { x0: -8, x1: -5, a: 1.15, h: 0, k: 1.1 })
              (if (str/endsWith @payload.id "t3-r")
                (emit TAYLOR_CURVE_MOD_ADD { x0: 5, x1: 8, a: 1.15, h: 0, k: 1.1 })
                null))))
        (if (!= @payload.kind "star")
          (emit TAYLOR_BURST { particles: [ { id: "narrative-boost", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: (if (str/endsWith @payload.id "linear") "+x/2" "−x³/48"), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 } ] })
          null)
    }

    emits {
      TAYLOR_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; term pads lift/tilt the sine road in the edge regions."
        @tier "domain"
      TAYLOR_BURST -> external {
        particles : [RiyaTaylorFx]
      }
        @description "Particle batch spawned on a term-pad boost narrative; fx-particles fades it."
        @tier "domain"
    }

    listens {
      TAYLOR_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "taylor"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaTaylorClear -> @rebindable RiyaTaylorState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "TAYLOR_NEXT", variant: "primary" } ]
        })

      TAYLOR_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      TAYLOR_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-taylor"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Taylor clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "You skated the whole wave — the line and the cubic only ever approximate it near 0."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-taylor" as RiyaTaylorPage -> TaylorLevelData, TaylorBody, TaylorGate, TaylorFx, TaylorPickup, TaylorTutorial, RiyaTaylorGenre, RiyaTaylorPlay, TaylorChallenge, RiyaTaylorClear
